    ]
    database141_lines = [
        diagnostic["formatted"]
        for diagnostic in genus_diagnostics
        if diagnostic.get("code") == "DATABASE-141"
    ]

    mapped_owned_errors = []
    warning_lines = []
    suggested = []
    summary_parts = []

    if ignorable_library_info_lines:
        warning_lines.extend(
            [
                "Non-blocking Liberty compatibility info: " + line
